using System.Collections;
using UnityEngine;

public class HandAxeBinder : MonoBehaviour
{
    Transform axe, hand, upperArm, lowerArm, spine, originalParent;
    Vector3 originalPos; Quaternion originalRot; bool lastActive,bound;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)] static void Install(){new GameObject("Hand Axe Runtime Binder").AddComponent<HandAxeBinder>();}
    IEnumerator Start(){for(int i=0;i<600&&!bound;i++){var p=GameObject.Find("Lumberjack Player");var a=FindInactiveByName("Axe Pivot");if(p!=null&&a!=null){Animator anim=p.GetComponentInChildren<Animator>(true);if(anim!=null&&anim.isHuman){hand=anim.GetBoneTransform(HumanBodyBones.RightHand);upperArm=anim.GetBoneTransform(HumanBodyBones.RightUpperArm);lowerArm=anim.GetBoneTransform(HumanBodyBones.RightLowerArm);spine=anim.GetBoneTransform(HumanBodyBones.Spine);}if(hand==null)hand=FindHand(p.transform);if(hand!=null){axe=a;originalParent=axe.parent;originalPos=axe.localPosition;originalRot=axe.localRotation;bound=true;}}if(!bound)yield return null;}}
    Transform FindInactiveByName(string target){foreach(var t in Resources.FindObjectsOfTypeAll<Transform>())if(t.gameObject.scene.IsValid()&&t.name==target)return t;return null;}
    void LateUpdate(){if(!bound||axe==null||hand==null)return;bool active=axe.gameObject.activeSelf;if(active&&!lastActive)StartCoroutine(HandSwing());lastActive=active;}
    IEnumerator HandSwing(){axe.SetParent(hand,false);axe.localPosition=new Vector3(.02f,.04f,.02f);axe.localRotation=Quaternion.Euler(2,8,92);Quaternion h0=hand.localRotation,u0=upperArm!=null?upperArm.localRotation:Quaternion.identity,l0=lowerArm!=null?lowerArm.localRotation:Quaternion.identity,s0=spine!=null?spine.localRotation:Quaternion.identity;Quaternion hWind=h0*Quaternion.Euler(-32,0,-30),hHit=h0*Quaternion.Euler(58,-10,34);Quaternion uWind=u0*Quaternion.Euler(-48,20,-42),uHit=u0*Quaternion.Euler(62,-12,34);Quaternion lWind=l0*Quaternion.Euler(-42,0,-26),lHit=l0*Quaternion.Euler(46,0,24);Quaternion sWind=s0*Quaternion.Euler(-10,-20,-5),sHit=s0*Quaternion.Euler(14,20,5);yield return Pose(.28f,h0,hWind,u0,uWind,l0,lWind,s0,sWind);yield return new WaitForSeconds(.08f);yield return Pose(.20f,hWind,hHit,uWind,uHit,lWind,lHit,sWind,sHit);yield return new WaitForSeconds(.10f);yield return Pose(.24f,hHit,h0,uHit,u0,lHit,l0,sHit,s0);hand.localRotation=h0;if(upperArm!=null)upperArm.localRotation=u0;if(lowerArm!=null)lowerArm.localRotation=l0;if(spine!=null)spine.localRotation=s0;if(axe!=null){axe.SetParent(originalParent,false);axe.localPosition=originalPos;axe.localRotation=originalRot;}}
    IEnumerator Pose(float duration,Quaternion ha,Quaternion hb,Quaternion ua,Quaternion ub,Quaternion la,Quaternion lb,Quaternion sa,Quaternion sb){float t=0;while(t<1&&axe!=null){t+=Time.deltaTime/duration;float e=Mathf.SmoothStep(0,1,t);hand.localRotation=Quaternion.Slerp(ha,hb,e);if(upperArm!=null)upperArm.localRotation=Quaternion.Slerp(ua,ub,e);if(lowerArm!=null)lowerArm.localRotation=Quaternion.Slerp(la,lb,e);if(spine!=null)spine.localRotation=Quaternion.Slerp(sa,sb,e);yield return null;}}
    Transform FindHand(Transform root){Transform fallback=null;foreach(var t in root.GetComponentsInChildren<Transform>(true)){string n=t.name.ToLowerInvariant().Replace(" ","");if(n.Contains("righthand")||n.Contains("hand_r")||n.Contains("hand.r")||n.Contains("r_hand"))return t;if(fallback==null&&n.Contains("hand")&&(n.Contains("right")||n.EndsWith("r")))fallback=t;}return fallback;}
}
